shellCommands.command:
/bin/bash -lc "cat > src/App.tsx <<'EOF'
import {useEffect, useRef, useState} from 'react';
import {AsideHeader} from '@gravity-ui/navigation';
import {Button, Card, Checkbox, Icon, Modal, Progress, Select, Switch, Text, TextInput, ThemeProvider} from '@gravity-ui/uikit';
import {ArrowRight, ArrowUpRight, Bell, Calendar, Check, ChevronDown, ChevronRight, CircleCheck, CircleQuestion, Clock, Ellipsis, Flag, Folder, LayoutCells, Magnifier, Moon, Plus, Rocket, Sparkles, SquareListUl, Sun, Xmark} from '@gravity-ui/icons';
import './styles.css';

type Page = 'overview' | 'projects' | 'tasks';
type Project = {id: string; title: string; description: string; color: string; icon: number; progress: number; total: number; date: string; status: 'active' | 'done' | 'archived'};
type Task = {id: string; title: string; project: string; date: string; priority: 'high' | 'medium' | 'low'; done: boolean};
const initialProjects: Project[] = [
  {id:'website', title:'Редизайн сайта', description:'Новый взгляд на наш цифровой дом', color:'mint', icon:0, progress:68, total:24, date:'12 ноя', status:'active'},
  {id:'app', title:'Мобильное приложение', description:'Полезный продукт — всегда под рукой', color:'purple', icon:1, progress:42, total:18, date:'20 ноя', status:'active'},
  {id:'brand', title:'Бренд-платформа', description:'Смыслы, которые нас объединяют', color:'peach', icon:2, progress:85, total:12, date:'8 ноя', status:'active'},
  {id:'research', title:'Исследование аудитории', description:'Ближе к людям, для которых создаём', color:'blue', icon:2, progress:100, total:8, date:'2 ноя', status:'done'},
];
const initialTasks: Task[] = [
  {id:'1', title:'Подготовить макеты главной страницы', project:'website', date:'Сегодня', priority:'high', done:false},
  {id:'2', title:'Согласовать пользовательский сценарий', project:'app', date:'Сегодня', priority:'medium', done:false},
  {id:'3', title:'Собрать референсы для айдентики', project:'brand', date:'Завтра', priority:'low', done:false},
  {id:'4', title:'Обновить компоненты дизайн-системы', project:'website', date:'Завтра', priority:'medium', done:false},
  {id:'5', title:'Провести интервью с пользователями', project:'research', date:'2 ноя', priority:'high', done:true},
  {id:'6', title:'Описать ценности бренда', project:'brand', date:'Сегодня', priority:'medium', done:true},
];
const pageNames = {overview:'Обзор', projects:'Проекты', tasks:'Мои задачи'};
const photos = [
  'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=80&h=80&fit=crop&crop=faces',
  'https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=80&h=80&fit=crop&crop=faces',
  'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=80&h=80&fit=crop&crop=faces',
];
function readSaved<T,>(key: string, fallback: T): T {try {const value = localStorage.getItem(key); return value ? JSON.parse(value) : fallback;} catch {return fallback;}}
function save(key: string, value: unknown) {try {localStorage.setItem(key, JSON.stringify(value));} catch { /* App remains usable when browser storage is unavailable. */ }}
function getPage(): Page {const page = window.location.hash.replace('#/', '').split('?')[0]; return page === 'projects' || page === 'tasks' ? page : 'overview';}
function BrandIcon() {return <svg viewBox=\"0 0 32 32\" fill=\"none\"><path d=\"m16 3 6 10-6 3-6-3 6-10Zm13 13-10 6-3-6 3-6 10 6ZM16 29l-6-10 6-3 6 3-6 10ZM3 16l10-6 3 6-3 6-10-6Z\" fill=\"currentColor\"/></svg>;}
function Avatars({count=3}: {count?:number}) {return <div className=\"avatars\">{photos.slice(0,count).map((photo,i)=><span className=\"avatar\" key={photo} style={{zIndex:4-i}}><span>{['АК','МС','ДВ'][i]}</span><img src={photo} alt={['Алексей Ковалёв','Мария Смирнова','Дмитрий Волков'][i]} onError={e=>{e.currentTarget.style.display='none';}}/></span>)}<span className=\"avatar avatar-more\">+{count === 2 ? 2 : 1}</span></div>;}

export function App() {
  const [theme,setTheme] = useState<'light'|'dark'>(()=>readSaved('tochka-theme','light'));
  const [page,setPage] = useState<Page>(getPage);
  const [compact,setCompact] = useState(()=>window.innerWidth < 1050);
  const [projects,setProjects] = useState<Project[]>(()=>readSaved('tochka-projects',initialProjects));
  const [tasks,setTasks] = useState<Task[]>(()=>readSaved('tochka-tasks',initialTasks));
  const [query,setQuery] = useState('');
  const [projectFilter,setProjectFilter] = useState('active');
  const [taskFilter,setTaskFilter] = useState('all');
  const [modal,setModal] = useState<'project'|'task'|'notifications'|'help'|'workspace'|'profile'|null>(null);
  const [detail,setDetail] = useState<string|null>(null);
  const [name,setName] = useState('');
  const [description,setDescription] = useState('');
  const [selectedProject,setSelectedProject] = useState(['website']);
  const [priority,setPriority] = useState(['medium']);
  const [due,setDue] = useState(['Сегодня']);
  const [error,setError] = useState(false);
  const searchRef = useRef<HTMLInputElement>(null);
  useEffect(()=>{const onHash=()=>{setPage(getPage());setQuery('');}; window.addEventListener('hashchange',onHash); return ()=>window.removeEventListener('hashchange',onHash);},[]);
  useEffect(()=>{save('tochka-theme',theme);},[theme]);
  useEffect(()=>{save('tochka-projects',projects);},[projects]);
  useEffect(()=>{save('tochka-tasks',tasks);},[tasks]);
  useEffect(()=>{const onKey=(event:KeyboardEvent)=>{if((event.metaKey||event.ctrlKey)&&event.key==='k'){event.preventDefault();searchRef.current?.focus();}};window.addEventListener('keydown',onKey);return()=>window.removeEventListener('keydown',onKey);},[]);
  const navigate=(next:Page)=>{setPage(next);setQuery('');window.location.hash="'`/${next}`;};
  const openCreate=(kind:'"'project'|'task', projectId?:string)=>{setName('');setDescription('');setError(false);setPriority(['medium']);setDue(['Сегодня']);setSelectedProject([projectId||projects.find(p=>p.status==='active')?.id||projects[0]?.id||'']);setModal(kind);setDetail(null);};
  const addItem=()=>{
    if("'!name.trim()){setError(true);return;}
    if(modal==='"'project') {setProjects(prev=>[...prev,{id:crypto.randomUUID(),title:name.trim(),description:description.trim()||'Всё большое начинается с первого шага',color:['mint','purple','peach','blue'][prev.length%4],icon:prev.length%3,progress:0,total:0,date:'Без срока',status:'active'}]);setProjectFilter('active');navigate('projects');}
    else {setTasks(prev=>[{id:crypto.randomUUID(),title:name.trim(),project:selectedProject[0],date:due[0],priority:priority[0] as Task['priority'],done:false},...prev]);navigate('tasks');setTaskFilter('all');}
    setModal(null);
  };
  const toggleTask=(id:string)=>setTasks(prev=>prev.map(task=>task.id===id?{...task,done:"'!task.done}:task));
  const matches=(text:string)=>text.toLocaleLowerCase('"'ru').includes(query.toLocaleLowerCase('ru').trim());
  const activeProjects=projects.filter(p=>p.status==='active');
  const visibleProjects=projects.filter(p=>(projectFilter==='all'||p.status===projectFilter)&&matches(p.title+' '+p.description));
  const visibleTasks=tasks.filter(t=>matches(t.title+' '+(projects.find(p=>p.id===t.project)?.title||''))&&(taskFilter==='all'||(taskFilter==='today'&&t.date==='Сегодня'&&"'!t.done)||(taskFilter==='"'done'&&t.done)||(taskFilter==='open'&&"'!t.done)));
  const completed=tasks.filter(t=>t.done).length;
  const detailProject=projects.find(p=>p.id===detail);
  const SectionTitle=({title,action,onClick}: {title:string;action?:string;onClick?:()=>void})=><div className="section-heading"><Text variant="subheader-3">{title}</Text>{action&&<Button view="flat" className="text-action" onClick={onClick}>{action}<Icon data={ArrowRight} size={15}/></Button>}</div>;
  const TaskRow=({task}: {task:Task})=>{const project=projects.find(p=>p.id===task.project);return <div className={`task-row ${task.done?'"'task-done':''}"'`}><Checkbox checked={task.done} onUpdate={()=>toggleTask(task.id)} size="l" controlProps={{'"'aria-label':"'`Выполнено: ${task.title}`}}/><div className="task-name"><span>{task.title}</span><div className="task-project"><i className={`project-dot ${project?.color||'"'mint'}"'`}/>{project?.title||'"'Без проекта'}</div></div><span className={"'`task-priority ${task.priority}`} title={{high:'"'Высокий приоритет',medium:'Средний приоритет',low:'Низкий приоритет'}[task.priority]}><Icon data={Flag} size={14}/></span><span className={"'`task-date ${task.date==='"'Сегодня'&&"'!task.done?'"'today':''}"'`}>{task.date}</span></div>;};
  const ProjectCard=({project}: {project:Project})=><Card className={`project-card ${project.color}`} view="outlined"><div className="project-top"><span className={`project-icon ${project.color}`}><Icon data={[LayoutCells,Rocket,Sparkles][project.icon]} size={22}/></span><span className={`status-pill ${project.status==='"'done'?'completed':''}"'`}><i/>{project.status==='"'done'?'Завершён':project.status==='archived'?'В архиве':'В работе'}</span><Button view=\"flat\" size=\"s\" aria-label={"'`Открыть ${project.title}`} onClick={()=>setDetail(project.id)}><Icon data={Ellipsis} size={20}/></Button></div><Button view="flat" className="project-title" onClick={()=>setDetail(project.id)}>{project.title}</Button><p className="project-description">{project.description}</p><div className="project-progress-label"><span>Прогресс</span><strong>{project.progress}%</strong></div><Progress value={project.progress} size="xs" className={`project-progress ${project.color}`}/><div className="project-meta"><span><Icon data={CircleCheck} size={14}/>{Math.round(project.total*project.progress/100)} / {project.total} задач</span><span><Icon data={Calendar} size={14}/>{project.date}</span></div><div className="project-bottom"><Avatars count={project.icon===1?2:3}/><Button view="flat" size="s" aria-label={`Подробнее: ${project.title}`} onClick={()=>setDetail(project.id)}><Icon data={ArrowUpRight} size={17}/></Button></div></Card>;
  const Empty=({text}: {text:string})=><div className="empty-state"><Icon data={Magnifier} size={30}/><Text variant="subheader-2">{text}</Text><span>Попробуйте изменить поиск или фильтр.</span><Button view="outlined" onClick={()=>{setQuery('"'');setProjectFilter('all');setTaskFilter('all');}}>Сбросить фильтры</Button></div>;

  return <ThemeProvider theme={theme}><AsideHeader className=\"app-shell\" compact={compact} onChangeCompact={setCompact} hideCollapseButton hideSectionDividers logo={{text:()=> <span className=\"wordmark\">точка<span>®</span></span>,icon:BrandIcon,iconSize:32,iconClassName:'brand-symbol',href:'#/overview','aria-label':'Точка — на главную'}}
    aboveMenuContent={<div className={"'`sidebar-intro ${compact?'"'is-compact':''}"'`}>{!compact&&<><Button view="outlined" size="xl" className="workspace-selector" onClick={()=>setModal('"'workspace')}><span className=\"workspace-icon\">S</span><span>Студия «Среда»</span><Icon data={ChevronDown} size={14}/></Button><div className=\"nav-caption\">РАБОЧЕЕ ПРОСТРАНСТВО</div></>}</div>}
    menuItems={[
      {id:'overview',title:'Обзор',icon:LayoutCells,current:page==='overview',onItemClick:()=>navigate('overview'),className:'main-nav-item'},
      {id:'projects',title:'Проекты',icon:Folder,current:page==='projects',onItemClick:()=>navigate('projects'),className:'main-nav-item',rightAdornment:compact?undefined:<span className=\"nav-count\">{activeProjects.length}</span>},
      {id:'tasks',title:'Мои задачи',icon:CircleCheck,current:page==='tasks',onItemClick:()=>navigate('tasks'),className:'main-nav-item',rightAdornment:compact?undefined:<span className=\"nav-count\">{tasks.filter(t=>"'!t.done).length}</span>},
      ...(!compact?[{id:'"'favorites-label',title:<span className=\"nav-caption favorites-caption\">ИЗБРАННЫЕ ПРОЕКТЫ</span>,type:'regular' as const,className:'favorites-label'},...activeProjects.slice(0,3).map(project=>({id:"'`fav-${project.id}`,title:<span className="favorite-label"><i className={`project-dot ${project.color}`}/>{project.title}</span>,onItemClick:()=>setDetail(project.id),className:'"'favorite-nav-item'}))]:[]),
    ]}
    renderFooter={()=> <div className={"'`sidebar-footer ${compact?'"'is-compact':''}"'`}>{!compact&&<><div className="ideas-card"><span className="ideas-icon"><Icon data={Sparkles} size={20}/></span><Text variant="subheader-2">От идеи — к результату</Text><p>Дайте новой идее своё место.</p><Button view="outlined" width="max" onClick={()=>openCreate('"'project')}><Icon data={Plus} size={15}/>Создать проект</Button></div><div className=\"theme-control\"><Icon data={theme==='light'?Sun:Moon} size={18}/><span>{theme==='light'?'Светлая тема':'Тёмная тема'}</span><Switch size=\"m\" checked={theme==='dark'} onUpdate={checked=>setTheme(checked?'dark':'light')} controlProps={{'aria-label':'Тёмная тема'}}/></div><Button view=\"flat\" className=\"help-button\" onClick={()=>setModal('help')}><Icon data={CircleQuestion} size={18}/>Помощь и поддержка<Icon data={ArrowUpRight} size={14}/></Button></>}{compact&&<Button view=\"flat\" aria-label=\"Переключить тему\" onClick={()=>setTheme(theme==='light'?'dark':'light')}><Icon data={theme==='light'?Sun:Moon} size={20}/></Button>}<Button view=\"flat\" className=\"profile-button\" onClick={()=>setModal('profile')}><span className=\"profile-avatar\"><img src={photos[0]} alt=\"\" onError={e=>{e.currentTarget.style.display='none';}}/></span>{"'!compact&&<><span className="profile-info"><strong>Алексей Ковалёв</strong><span>Личное пространство</span></span><Icon data={ChevronDown} size={14}/></>}</Button></div>}
    renderContent={()=> <div className="workspace-main"><header className="topbar"><div className="breadcrumbs"><span>Рабочее пространство</span><Icon data={ChevronRight} size={13}/><strong>{pageNames[page]}</strong></div><div className="topbar-tools"><TextInput controlRef={searchRef} className="global-search" size="m" view="clear" placeholder="Поиск по пространству" value={query} onUpdate={setQuery} startContent={<Icon data={Magnifier} size={16}/>} endContent={<kbd>⌘ K</kbd>} controlProps={{'"'aria-label':'Поиск по пространству'}}/><span className=\"topbar-divider\"/><Button view=\"flat\" className=\"notification-button\" aria-label=\"Уведомления\" onClick={()=>setModal('notifications')}><Icon data={Bell} size={20}/><i/></Button><span className=\"topbar-avatar\"><img src={photos[0]} alt=\"Алексей\" onError={e=>{e.currentTarget.style.display='none';}}/></span></div></header>
    <main className=\"page-content\"><div className=\"page-heading\"><div><div className=\"eyebrow\">ВАШЕ РАБОЧЕЕ ПРОСТРАНСТВО</div><Text variant=\"header-1\" className=\"page-title\">{page==='overview'?'Всё важное — в одном месте':page==='projects'?'Большие идеи. Реальные проекты.':'Маленькие шаги к большим целям.'}</Text><p className=\"page-subtitle\">{page==='overview'?'Планируйте, создавайте и двигайтесь вперёд вместе с командой.':page==='projects'?'От первого наброска до финального результата — вместе.':'Освободите голову: всё, что нужно сделать, уже здесь.'}</p></div><Button view=\"action\" size=\"l\" className=\"create-button\" onClick={()=>openCreate(page==='tasks'?'task':'project')}><Icon data={Plus} size={17}/>{page==='tasks'?'Новая задача':'Новый проект'}</Button></div>
    {page==='overview'? <>
      <section className=\"welcome-banner\"><div className=\"welcome-copy\"><div className=\"welcome-kicker\"><span className=\"live-dot\"/>СРЕДА, 4 НОЯБРЯ</div><Text variant=\"header-1\" className=\"welcome-title\">Хороший день для хороших идей<span>✦</span></Text><p>У вас {tasks.filter(t=>t.date==='Сегодня'&&"'!t.done).length} задачи на сегодня. Начнём с самого важного?</p><Button view="outlined" size="l" className="welcome-button" onClick={()=>{setTaskFilter('"'today');navigate('tasks');}}>К моим задачам<Icon data={ArrowRight} size={16}/></Button></div><div className=\"hero-art\" aria-hidden=\"true\"><div className=\"orbit orbit-one\"/><div className=\"orbit orbit-two\"/><div className=\"art-disc\"><BrandIcon/></div><span className=\"art-spark spark-one\">✦</span><span className=\"art-spark spark-two\">✧</span><span className=\"art-dot dot-one\"/><span className=\"art-dot dot-two\"/><div className=\"floating-card floating-card-back\"><span className=\"art-mini-icon\"><Icon data={Folder} size={19}/></span><div><b>Идея обретает форму</b><span className=\"art-line\"/><span className=\"art-line short\"/></div></div><div className=\"floating-card floating-card-front\"><span className=\"art-check\"><Icon data={Check} size={22}/></span><div><b>Ещё на шаг ближе</b><span>к большому результату</span></div><span className=\"tiny-confetti\">✦</span></div></div></section>
      <div className=\"stats-grid\">{[{title:'Активные проекты',value:activeProjects.length,icon:Folder,note:'Всё идёт по плану',color:'mint'},{title:'Задачи в работе',value:tasks.filter(t=>"'!t.done).length,icon:Clock,note:'"'Есть на чём сфокусироваться',color:'blue'},{title:'Завершено задач',value:completed,icon:CircleCheck,note:'Каждый шаг имеет значение',color:'purple'},{title:'Участники команды',value:4,icon:PersonsIcon,note:'Вместе получается больше',color:'peach'}].map(stat=><Card className=\"stat-card\" view=\"outlined\" key={stat.title}><div className=\"stat-top\"><span>{stat.title}</span><span className={"'`stat-icon ${stat.color}`}><Icon data={stat.icon} size={18}/></span></div><strong className="stat-value">{String(stat.value).padStart(2,'"'0')}</strong><span className=\"stat-note\">{stat.note}</span></Card>)}</div>
      <section className=\"projects-section\"><SectionTitle title=\"Проекты в работе\" action=\"Все проекты\" onClick={()=>{setProjectFilter('all');navigate('projects');}}/><div className=\"projects-grid\">{activeProjects.filter(p=>matches(p.title+' '+p.description)).slice(0,3).map(project=><ProjectCard key={project.id} project={project}/>)}{query&&"'!activeProjects.some(p=>matches(p.title+'"' '+p.description))&&<Empty text=\"Проекты не найдены\"/>}</div></section>
      <div className=\"lower-grid\"><section className=\"tasks-section\"><SectionTitle title=\"Ближайшие задачи\" action=\"Все задачи\" onClick={()=>{setTaskFilter('all');navigate('tasks');}}/><Card view=\"outlined\" className=\"task-list\">{tasks.filter(t=>"'!t.done&&matches(t.title)).slice(0,4).map(task=><TaskRow key={task.id} task={task}/>)}{!tasks.some(t=>!t.done&&matches(t.title))&&<Empty text="Пока нет открытых задач"/>}<Button className="add-task-inline" view="flat" onClick={()=>openCreate('"'task')}><Icon data={Plus} size={16}/>Добавить задачу</Button></Card></section><section className=\"activity-section\"><SectionTitle title=\"Активность команды\"/><Card view=\"outlined\" className=\"activity-card\"><div className=\"activity-item\"><span className=\"activity-avatar\"><img src={photos[1]} alt=\"Мария\"/></span><div><p><strong>Мария</strong> завершила задачу</p><span>Собрать мудборд для проекта</span><small>15 минут назад <i>·</i> Бренд-платформа</small></div></div><div className=\"activity-item\"><span className=\"activity-avatar\"><img src={photos[2]} alt=\"Дмитрий\"/></span><div><p><strong>Дмитрий</strong> добавил комментарий</p><span>«Отлично, двигаемся дальше"'!»</span><small>42 минуты назад <i>·</i> Редизайн сайта</small></div></div><div className="activity-item"><span className="activity-avatar activity-system"><Icon data={Folder} size={17}/></span><div><p>Создан проект <strong>«Бренд-платформа»</strong></p><span>Начало чего-то большого</span><small>Сегодня, 09:30</small></div></div><div className="activity-foot"><span className="live-dot"/>Вы в курсе всех событий</div></Card></section></div>
    </>:page==='"'projects'? <><div className=\"page-toolbar\"><div className=\"filter-tabs\">{[{id:'active',label:'В работе'},{id:'all',label:'Все проекты'},{id:'done',label:'Завершённые'},{id:'archived',label:'Архив'}].map(filter=><Button key={filter.id} view=\"flat\" selected={projectFilter===filter.id} className={projectFilter===filter.id?'filter-tab active':'filter-tab'} onClick={()=>setProjectFilter(filter.id)}>{filter.label}{filter.id==='active'&&<span className=\"tab-count\">{activeProjects.length}</span>}</Button>)}</div><span className=\"muted\">{visibleProjects.length} из {projects.length} проектов</span></div><div className=\"projects-grid full-projects\">{visibleProjects.map(project=><ProjectCard key={project.id} project={project}/>)}{"'!visibleProjects.length&&<Empty text={query?'"'Ничего не нашлось':'Здесь пока нет проектов'}/>}<Button className=\"new-project-tile\" view=\"outlined\" onClick={()=>openCreate('project')}><span className=\"new-project-content\"><span className=\"new-project-plus\"><Icon data={Plus} size={25}/></span><Text variant=\"subheader-2\">Новый проект</Text><span>Пусть хорошая идея станет реальностью</span></span></Button></div></>:<><div className=\"task-page-summary\"><span className=\"task-summary-icon\"><Icon data={CircleCheck} size={26}/></span><div><Text variant=\"subheader-2\">Каждая выполненная задача — маленькая победа</Text><p>Выполнено {completed} из {tasks.length} задач. Продолжайте в своём ритме.</p></div><Progress value={tasks.length?Math.round(completed/tasks.length*100):0} size=\"s\" className=\"summary-progress\"/></div><div className=\"page-toolbar\"><div className=\"filter-tabs\">{[{id:'all',label:'Все задачи'},{id:'today',label:'На сегодня'},{id:'open',label:'В работе'},{id:'done',label:'Выполненные'}].map(filter=><Button key={filter.id} view=\"flat\" selected={taskFilter===filter.id} className={taskFilter===filter.id?'filter-tab active':'filter-tab'} onClick={()=>setTaskFilter(filter.id)}>{filter.label}</Button>)}</div><Button view=\"outlined\" onClick={()=>openCreate('task')}><Icon data={Plus} size={16}/>Добавить</Button></div><Card view=\"outlined\" className=\"task-list full-task-list\"><div className=\"task-list-header\"><span>НАЗВАНИЕ ЗАДАЧИ</span><span>ПРИОРИТЕТ</span><span>СРОК</span></div>{visibleTasks.map(task=><TaskRow task={task} key={task.id}/>)}{"'!visibleTasks.length&&<Empty text="Задачи не найдены"/>}</Card></>}
    <footer className="page-footer"><span>Меньше суеты. Больше смысла.</span><span><span className="footer-brand">точка</span> — пространство для ваших идей</span></footer></main></div>}/>
